begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
-- All fixtures and writes roll back; no Auth email is sent by these SQL RPCs.
insert into auth.users(id,email) values ('1a000000-0000-4000-8000-000000000001','invitation-admin@example.test'),('1a000000-0000-4000-8000-000000000002','invitation-org-admin@example.test'),('1a000000-0000-4000-8000-000000000003','student-invite@example.test');
insert into public.users(id,account_status) values ('1a000000-0000-4000-8000-000000000001','active'),('1a000000-0000-4000-8000-000000000002','active');
insert into public.organizations(id,name,slug) values ('2a000000-0000-4000-8000-000000000001','Invitation regression','invitation-rpc-regression');
insert into public.sites(id,organization_id,name,code) values ('3a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','Invitation Site','INV-RPC');
insert into public.people(id,first_name,last_name) values ('4a000000-0000-4000-8000-000000000001','Invitation','Student');
insert into public.students(id,first_name,last_name,grade_level,organization_id,primary_site_id,person_id) values ('7a000000-0000-4000-8000-000000000001','Invitation','Student','4','2a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000001','4a000000-0000-4000-8000-000000000001');
insert into public.role_assignments(user_id,role_key,organization_id,status) values ('1a000000-0000-4000-8000-000000000001','platform_admin',null,'active'),('1a000000-0000-4000-8000-000000000002','organization_admin','2a000000-0000-4000-8000-000000000001','active');
-- Pick a tenant date that differs from UTC, so replacing the calendar helper
-- with database current_date causes the boundary tests to fail.
update public.sites set timezone=case when (now() at time zone 'Pacific/Kiritimati')::date <> (now() at time zone 'UTC')::date then 'Pacific/Kiritimati' else 'Pacific/Honolulu' end where id='3a000000-0000-4000-8000-000000000001';
select set_config('test.invitation_today',(select (now() at time zone timezone)::date::text from public.sites where id='3a000000-0000-4000-8000-000000000001'),true);
update public.students set enrollment_start_date=current_setting('test.invitation_today')::date, enrollment_end_date=current_setting('test.invitation_today')::date where id='7a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','missing identity is rejected by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','missing identity is rejected by public.mac_admin_link_invited_student_login');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','organization administrator is rejected by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','organization administrator is rejected by public.mac_admin_link_invited_student_login');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test'),'7a000000-0000-4000-8000-000000000001'::uuid,'platform administrator validates tenant-calendar boundary enrollment');
select throws_ok($$select public.mac_admin_validate_student_login_invitation(null,'x@example.test')$$,'22023','student and email are required','validate rejects missing student');
select throws_ok($$select public.mac_admin_link_invited_student_login(null,'7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','student, user, and email are required','link rejects missing Auth user');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','wrong@example.test')$$,'22023','invited Auth identity does not match the requested email','link rejects Auth email mismatch');
select throws_ok($$select public.mac_admin_link_invited_student_login('00000000-0000-0000-0000-000000000000','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','invited Auth identity does not match the requested email','link rejects nonexistent Auth identity');
reset role; update public.students set enrollment_end_date=null, enrollment_start_date=current_setting('test.invitation_today')::date+1 where id='7a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','student enrollment is not current','future enrollment denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','student enrollment is not current','future enrollment denied by public.mac_admin_link_invited_student_login');
reset role; update public.students set enrollment_start_date=current_setting('test.invitation_today')::date where id='7a000000-0000-4000-8000-000000000001';
reset role; update public.students set enrollment_start_date=current_setting('test.invitation_today')::date-2, enrollment_end_date=current_setting('test.invitation_today')::date-1 where id='7a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','student enrollment is not current','expired enrollment denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','student enrollment is not current','expired enrollment denied by public.mac_admin_link_invited_student_login');
reset role; update public.students set enrollment_end_date=current_setting('test.invitation_today')::date where id='7a000000-0000-4000-8000-000000000001';
reset role; update public.students set primary_site_id=null where id='7a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','active enrolled student with a canonical person and site was not found','missing site denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','active enrolled student with a canonical person and site was not found','missing site denied by public.mac_admin_link_invited_student_login');
reset role; update public.students set primary_site_id='3a000000-0000-4000-8000-000000000001' where id='7a000000-0000-4000-8000-000000000001';
reset role; update public.students set enterprise_status='inactive' where id='7a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','active enrolled student with a canonical person and site was not found','inactive student denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'22023','active enrolled student with a canonical person and site was not found','inactive student denied by public.mac_admin_link_invited_student_login');
reset role; update public.students set enterprise_status='active' where id='7a000000-0000-4000-8000-000000000001';
reset role; update public.people set primary_email='different@example.test' where id='4a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'23505','student person record has a different primary email','person email conflict denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'23505','student person record has a different primary email','person email conflict denied by public.mac_admin_link_invited_student_login');
reset role; update public.people set primary_email=null where id='4a000000-0000-4000-8000-000000000001';
select is((select count(*) from public.users where id='1a000000-0000-4000-8000-000000000003'),0::bigint,'failed attempts do not provision an application user');
select is((select count(*) from public.student_enrollment_events where student_id='7a000000-0000-4000-8000-000000000001' and event_type='login_invited'),0::bigint,'failed attempts create no invitation audit event');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001',' STUDENT-INVITE@EXAMPLE.TEST '),'7a000000-0000-4000-8000-000000000001'::uuid,'successful linking normalizes email and preserves calendar dependency');
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'23505','this student or email already has an application login','duplicate denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'23505','this student or email already has an application login','duplicate denied by public.mac_admin_link_invited_student_login');
reset role;
select is((select account_status from public.users where id='1a000000-0000-4000-8000-000000000003'),'invited','new user remains invited until authenticated activation');
select is((select person_id from public.users where id='1a000000-0000-4000-8000-000000000003'),'4a000000-0000-4000-8000-000000000001'::uuid,'link preserves canonical person');
select is((select count(*) from public.profiles where user_id='1a000000-0000-4000-8000-000000000003' and organization_id='2a000000-0000-4000-8000-000000000001' and site_id='3a000000-0000-4000-8000-000000000001' and person_id='4a000000-0000-4000-8000-000000000001' and role='student'),1::bigint,'profile is uniquely provisioned in the student tenant and site');
select is((select count(*) from public.role_assignments where user_id='1a000000-0000-4000-8000-000000000003' and role_key='student' and organization_id='2a000000-0000-4000-8000-000000000001' and site_id='3a000000-0000-4000-8000-000000000001' and status='active'),1::bigint,'link grants exactly the scoped student role');
select is((select primary_email from public.people where id='4a000000-0000-4000-8000-000000000001'),'student-invite@example.test','canonical email stored normalized');
select is((select count(*) from public.student_enrollment_events where student_id='7a000000-0000-4000-8000-000000000001' and event_type='login_invited' and actor_user_id='1a000000-0000-4000-8000-000000000001' and organization_id='2a000000-0000-4000-8000-000000000001' and site_id='3a000000-0000-4000-8000-000000000001'),1::bigint,'one attributed invitation audit event remains after duplicate rejection');
select set_config('mac.audit_reason','Expire regression administrator',true); update public.role_assignments set valid_from=now()-interval '2 days',valid_until=now()-interval '1 day' where user_id='1a000000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"1a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.mac_admin_validate_student_login_invitation('7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','expired platform admin denied by public.mac_admin_validate_student_login_invitation');
select throws_ok($$select public.mac_admin_link_invited_student_login('1a000000-0000-4000-8000-000000000003','7a000000-0000-4000-8000-000000000001','student-invite@example.test')$$,'42501','not authorized to invite Student logins','expired platform admin denied by public.mac_admin_link_invited_student_login');
reset role;
select ok(not has_function_privilege('anon','public.mac_admin_validate_student_login_invitation(uuid,text)','execute') and has_function_privilege('authenticated','public.mac_admin_validate_student_login_invitation(uuid,text)','execute'),'RPC ACL requires authenticated caller: mac_admin_validate_student_login_invitation(uuid,text)');
select ok(not has_function_privilege('anon','public.mac_admin_link_invited_student_login(uuid,uuid,text)','execute') and has_function_privilege('authenticated','public.mac_admin_link_invited_student_login(uuid,uuid,text)','execute'),'RPC ACL requires authenticated caller: mac_admin_link_invited_student_login(uuid,uuid,text)');
select * from finish();
rollback;
